      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00218",
          "explanation": "The doctor provided a named service and near-term booking target.",
          "quote": "现在可以先约1周后的骨科号"
        }
      ],
      "explanation": "The family received sequenced near-term actions for medication review, wound care, ENT evaluation, spine follow-up, and emergency escalation.",
